"""The OBS database (DuckDB locally; Snowflake DDL is generated by :mod:`.generate`).

Schemas (Section 7.3):

- ``RAW``       immutable, append-only archive of every harvest-contract table plus ``ACCOUNT_NAME`` and
                load metadata (``_ROW_HASH``, ``_HARVEST_ID``, ``_LOADED_AT``). Rows are de-duplicated by
                row hash on load, so overlapping harvests never duplicate history and the archive keeps
                rows after the source's native retention window has dropped them. Full-snapshot sources
                store each distinct row once and record which rows each harvest saw in
                ``RAW.SNAPSHOT_MEMBERSHIP``. ``RAW.HARVEST_LOG`` records every harvest step.
- ``CURATED``   conformed facts and dimensions (views over RAW).
- ``KPI``       one table per implemented KPI (dynamic tables in Snowflake).
- ``SEMANTIC``  certified KPI definitions and a long-format value view for the agent.
- ``OPS``       alert events and routing tests (append-only).

RAW immutability is enforced by :meth:`ObsDatabase._guard` (UPDATE / DELETE / MERGE / TRUNCATE / DROP /
ALTER / CREATE OR REPLACE / INSERT OVERWRITE on RAW are refused) and, in Snowflake, by grants: the loader
role receives INSERT and SELECT only (see ``generated/observability/snowflake/02_grants.sql``).
"""

from __future__ import annotations

import json
import threading
from contextlib import contextmanager
from datetime import datetime
from decimal import Decimal
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence

import duckdb
import sqlglot
from sqlglot import exp

from altitude.core.errors import AppendOnlyViolation
from altitude.synthetic.schema import HARVEST_SCHEMA

SCHEMAS = ("RAW", "CURATED", "KPI", "SEMANTIC", "OPS")
IMMUTABLE_SCHEMAS = {"raw"}
IMMUTABLE_TABLES = {("ops", "alert_event"), ("ops", "routing_test")}

META_COLUMNS: dict[str, str] = {
    "_ROW_HASH": "VARCHAR",
    "_HARVEST_ID": "VARCHAR",
    "_LOADED_AT": "TIMESTAMP",
}

HARVEST_LOG_COLUMNS: dict[str, str] = {
    "HARVEST_ID": "VARCHAR", "ACCOUNT_NAME": "VARCHAR", "SOURCE_TABLE": "VARCHAR", "STRATEGY": "VARCHAR",
    "AS_OF": "TIMESTAMP", "SINCE": "TIMESTAMP", "ROWS_READ": "BIGINT", "ROWS_INSERTED": "BIGINT",
    "ROWS_DUPLICATE": "BIGINT", "STATUS": "VARCHAR", "ERROR": "VARCHAR",
}

MEMBERSHIP_COLUMNS: dict[str, str] = {
    "ACCOUNT_NAME": "VARCHAR", "SOURCE_TABLE": "VARCHAR", "HARVEST_ID": "VARCHAR", "SNAPSHOT_DATE": "DATE",
    "AS_OF": "TIMESTAMP", "ROW_HASH": "VARCHAR",
}

ALERT_EVENT_COLUMNS: dict[str, str] = {
    "EVENT_ID": "VARCHAR", "ALERT_ID": "VARCHAR", "ALERT_CLASS": "VARCHAR", "ACCOUNT_NAME": "VARCHAR",
    "DIMENSION": "VARCHAR", "EVALUATED_FOR": "DATE", "SEVERITY": "VARCHAR", "ROUTE": "VARCHAR",
    "CHANNEL": "VARCHAR", "RUNBOOK": "VARCHAR", "OWNER_ROLE": "VARCHAR", "STATUS": "VARCHAR",
    "OBSERVED": "DOUBLE", "EXPECTED": "DOUBLE", "UPPER_BAND": "DOUBLE", "MESSAGE": "VARCHAR",
    "EVIDENCE": "VARCHAR", "OUTBOX_PATH": "VARCHAR",
}

ROUTING_TEST_COLUMNS: dict[str, str] = {
    "TEST_ID": "VARCHAR", "TESTED_FOR": "DATE", "ROUTE": "VARCHAR", "CHANNEL": "VARCHAR", "OK": "BOOLEAN",
    "DETAIL": "VARCHAR", "OUTBOX_PATH": "VARCHAR",
}

_MUTATING = (exp.Update, exp.Delete, exp.Drop, exp.TruncateTable, exp.Alter, exp.Merge)


def raw_columns(table: str) -> dict[str, str]:
    """RAW layout for a harvest-contract table: contract columns + ACCOUNT_NAME + load metadata."""
    cols = {c: ("VARCHAR" if t == "JSON" else t) for c, t in HARVEST_SCHEMA[table]["columns"].items()}
    if "ACCOUNT_NAME" not in cols:
        cols = {"ACCOUNT_NAME": "VARCHAR", **cols}
    return {**cols, **META_COLUMNS}




def contract_columns(table: str) -> dict[str, str]:
    return {c: ("VARCHAR" if t == "JSON" else t) for c, t in HARVEST_SCHEMA[table]["columns"].items()
            if c != "ACCOUNT_NAME"}


def row_hash_sql(table: str) -> str:
    """SQL expression for an archived row's content hash (account + table + contract columns).

    Computed in DuckDB over the *typed* values, so a row hashes identically however the source driver
    represented it (1 vs 1.0, Decimal vs float, datetime vs string). The account is the first parameter.
    """
    parts = ", ".join(f'CAST("{c}" AS VARCHAR)' for c in contract_columns(table))
    return f"md5(CAST(to_json([?::VARCHAR, '{table}', {parts}]) AS VARCHAR))"


def mutations(sql: str) -> list[tuple[str, str, str]]:
    """Return ``(operation, schema, table)`` for every mutating statement in ``sql`` (lower-case names)."""
    out: list[tuple[str, str, str]] = []
    try:
        statements = sqlglot.parse(sql, read="duckdb")
    except sqlglot.errors.ParseError:
        low = sql.lower()
        if "raw" in low and any(v in low for v in ("update", "delete", "truncate", "drop", "alter", "merge", "replace")):
            out.append(("UNPARSEABLE", "raw", "?"))
        return out
    for st in statements:
        if st is None:
            continue
        if isinstance(st, (exp.Use, exp.Set)) or (isinstance(st, exp.Command) and str(st.this).upper() in {"USE", "SET"}):
            out.append(("SESSION", "*", "*"))
            continue
        op = None
        if isinstance(st, _MUTATING):
            op = type(st).__name__.upper()
        elif isinstance(st, exp.Insert) and (st.args.get("overwrite") or st.args.get("alternative")):
            op = "INSERT OVERWRITE"
        elif isinstance(st, exp.Create) and st.args.get("replace"):
            op = "CREATE OR REPLACE"
        elif isinstance(st, exp.Command):
            verb = str(st.this).upper()
            if verb in {"TRUNCATE", "ALTER", "UPDATE", "DELETE", "MERGE", "DROP"}:
                words = str(st.expression or "").replace('"', "").split()
                name = words[1] if words and words[0].upper() in {"TABLE", "SCHEMA"} and len(words) > 1 else (
                    words[0] if words else "")
                parts = name.lower().split(".")
                schema = parts[-2] if len(parts) > 1 else (parts[0] if words and words[0].upper() == "SCHEMA" else "")
                out.append((verb, schema, parts[-1]))
            continue
        if op is None:
            continue
        if isinstance(st, exp.Drop) and str(st.args.get("kind", "")).upper() == "SCHEMA":
            for t in st.find_all(exp.Table):
                out.append((op, (t.db or t.name).lower(), "*"))
            continue
        target = st.this if isinstance(st, (exp.Update, exp.Delete, exp.Merge, exp.Insert, exp.Create, exp.Drop,
                                            exp.TruncateTable, exp.Alter)) else None
        tables = [target] if isinstance(target, exp.Table) else []
        if isinstance(target, exp.Schema) and isinstance(target.this, exp.Table):
            tables = [target.this]
        if not tables:
            tables = list(st.find_all(exp.Table))[:1]
        if isinstance(st, exp.TruncateTable):
            tables = list(st.expressions) or tables
        for t in tables:
            out.append((op, (t.db or "").lower(), t.name.lower()))
    return out


class ObsDatabase:
    """Guarded DuckDB connection holding the RAW / CURATED / KPI / SEMANTIC / OPS schemas."""

    def __init__(self, path: str | Path = ":memory:"):
        self.path = str(path)
        self._con = duckdb.connect(self.path)
        self._lock = threading.RLock()
        self._init_schemas()

    # ------------------------------------------------------------------ schema
    def _init_schemas(self) -> None:
        with self._lock:
            for s in SCHEMAS:
                self._con.execute(f"CREATE SCHEMA IF NOT EXISTS {s}")
            for table in HARVEST_SCHEMA:
                self._create("RAW", table, raw_columns(table))
            self._create("RAW", "HARVEST_LOG", HARVEST_LOG_COLUMNS)
            self._create("RAW", "SNAPSHOT_MEMBERSHIP", MEMBERSHIP_COLUMNS)
            self._create("OPS", "ALERT_EVENT", ALERT_EVENT_COLUMNS)
            self._create("OPS", "ROUTING_TEST", ROUTING_TEST_COLUMNS)

    def _create(self, schema: str, table: str, cols: Mapping[str, str]) -> None:
        body = ", ".join(f'"{c}" {t}' for c, t in cols.items())
        self._con.execute(f'CREATE TABLE IF NOT EXISTS {schema}."{table}" ({body})')

    # ------------------------------------------------------------------ guard
    @staticmethod
    def _guard(sql: str) -> None:
        for op, schema, table in mutations(sql):
            if op == "SESSION":
                raise AppendOnlyViolation("USE/SET statements are not permitted on the OBS database connection")
            if schema in IMMUTABLE_SCHEMAS or (schema, table) in IMMUTABLE_TABLES:
                raise AppendOnlyViolation(
                    f"{op} on {schema.upper()}.{table.upper()} is not permitted: RAW is an immutable, append-only archive"
                )

    def execute(self, sql: str, params: Sequence[Any] | None = None) -> None:
        self._guard(sql)
        with self._lock:
            self._con.execute(sql, _params(params))

    def query(self, sql: str, params: Sequence[Any] | None = None) -> list[dict[str, Any]]:
        self._guard(sql)
        with self._lock:
            cur = self._con.execute(sql, _params(params))
            cols = [d[0] for d in cur.description] if cur.description else []
            return [dict(zip(cols, row)) for row in cur.fetchall()]

    def scalar(self, sql: str, params: Sequence[Any] | None = None) -> Any:
        rows = self.query(sql, params)
        return next(iter(rows[0].values())) if rows else None

    def relation_exists(self, schema: str, name: str) -> bool:
        return bool(self._con.execute(
            "SELECT count(*) FROM information_schema.tables WHERE lower(table_schema)=lower(?) AND lower(table_name)=lower(?)",
            [schema, name]).fetchone()[0])

    def relations(self, schema: str) -> list[str]:
        rows = self._con.execute(
            "SELECT table_name FROM information_schema.tables WHERE lower(table_schema)=lower(?) ORDER BY 1", [schema]
        ).fetchall()
        return [r[0] for r in rows]

    # ------------------------------------------------------------------ append-only writes
    def _insert_rows(self, schema: str, table: str, cols: Mapping[str, str], rows: list[dict],
                     dedupe_on: str | None = None) -> int:
        """Insert ``rows`` (typed by ``cols``); with ``dedupe_on`` skip rows whose key already exists."""
        if not rows:
            return 0
        batch = _arrow_batch(rows, list(cols))
        select = ", ".join(f'TRY_CAST("{c}" AS {t}) AS "{c}"' for c, t in cols.items())
        where = ""
        if dedupe_on:
            where = f' WHERE "{dedupe_on}" NOT IN (SELECT "{dedupe_on}" FROM {schema}."{table}")'
        with self._lock:
            self._con.register("_obs_batch", batch)
            try:
                n = self._con.execute(f"SELECT count(*) FROM _obs_batch{where}").fetchone()[0]
                if n:
                    self._con.execute(f'INSERT INTO {schema}."{table}" SELECT {select} FROM _obs_batch{where}')
            finally:
                self._con.unregister("_obs_batch")
        return int(n)

    def append_raw(self, table: str, rows: Iterable[Mapping[str, Any]], *, account: str, harvest_id: str,
                   loaded_at: datetime) -> tuple[int, int, list[str]]:
        """Append rows to ``RAW.<table>``; returns ``(inserted, duplicates, distinct_row_hashes_in_batch)``.

        Rows whose content hash is already archived for this account are skipped, so re-reading an
        overlapping window (or the same snapshot twice) never duplicates history.
        """
        rows = list(rows)
        if not rows:
            return 0, 0, []
        contract = contract_columns(table)
        batch = _arrow_batch(rows, list(contract))
        typed = ", ".join(f'TRY_CAST("{c}" AS {t}) AS "{c}"' for c, t in contract.items())
        target = list(raw_columns(table))
        injected = {"ACCOUNT_NAME": "?::VARCHAR", "_HARVEST_ID": "?::VARCHAR", "_LOADED_AT": "?::TIMESTAMP"}
        values = {"ACCOUNT_NAME": account, "_HARVEST_ID": harvest_id, "_LOADED_AT": loaded_at}
        select = ", ".join(f'{injected[c]} AS "{c}"' if c in injected else f'"{c}"' for c in target)
        select_params = [values[c] for c in target if c in injected]
        new = (f'FROM _obs_stage WHERE "_ROW_HASH" NOT IN '
               f'(SELECT "_ROW_HASH" FROM RAW."{table}" WHERE ACCOUNT_NAME = ?)')
        col_list = ", ".join(f'"{c}"' for c in target)
        with self._lock:
            con = self._con
            con.register("_obs_batch", batch)
            try:
                con.execute(
                    f'CREATE OR REPLACE TEMP TABLE _obs_stage AS SELECT *, {row_hash_sql(table)} AS "_ROW_HASH" '
                    f"FROM (SELECT {typed} FROM _obs_batch) "
                    f'QUALIFY row_number() OVER (PARTITION BY "_ROW_HASH") = 1', [account])
                hashes = [r[0] for r in con.execute('SELECT "_ROW_HASH" FROM _obs_stage ORDER BY 1').fetchall()]
                n = int(con.execute(f"SELECT count(*) {new}", [account]).fetchone()[0])
                if n:
                    con.execute(f'INSERT INTO RAW."{table}" ({col_list}) SELECT {select} {new}',
                                select_params + [account])
                con.execute("DROP TABLE IF EXISTS _obs_stage")
            finally:
                con.unregister("_obs_batch")
        return n, len(hashes) - n, hashes

    def record_membership(self, table: str, account: str, harvest_id: str, as_of: datetime, hashes: list[str]) -> None:
        existing = self._con.execute(
            "SELECT count(*) FROM RAW.SNAPSHOT_MEMBERSHIP WHERE HARVEST_ID=? AND SOURCE_TABLE=? AND ACCOUNT_NAME=?",
            [harvest_id, table, account]).fetchone()[0]
        if existing:
            return  # re-run of the same harvest: membership already recorded (idempotent, append-only)
        rows = [{"ACCOUNT_NAME": account, "SOURCE_TABLE": table, "HARVEST_ID": harvest_id,
                 "SNAPSHOT_DATE": as_of.date(), "AS_OF": as_of, "ROW_HASH": h} for h in hashes]
        if not rows:  # an empty snapshot is still a snapshot: record a marker row with no hash
            rows = [{"ACCOUNT_NAME": account, "SOURCE_TABLE": table, "HARVEST_ID": harvest_id,
                     "SNAPSHOT_DATE": as_of.date(), "AS_OF": as_of, "ROW_HASH": None}]
        self._insert_rows("RAW", "SNAPSHOT_MEMBERSHIP", MEMBERSHIP_COLUMNS, rows)

    def log_harvest(self, entry: Mapping[str, Any]) -> None:
        self._insert_rows("RAW", "HARVEST_LOG", HARVEST_LOG_COLUMNS, [dict(entry)])

    def append_ops(self, table: str, rows: list[dict]) -> int:
        cols = {"ALERT_EVENT": ALERT_EVENT_COLUMNS, "ROUTING_TEST": ROUTING_TEST_COLUMNS}[table]
        return self._insert_rows("OPS", table, cols, rows)

    def watermark(self, table: str, column: str, account: str) -> Any:
        return self._con.execute(
            f'SELECT max("{column}") FROM RAW."{table}" WHERE ACCOUNT_NAME = ?', [account]).fetchone()[0]

    # ------------------------------------------------------------------ derived layers (mutable)
    def replace_view(self, schema: str, name: str, sql: str) -> None:
        if schema.lower() in IMMUTABLE_SCHEMAS:
            raise AppendOnlyViolation("views cannot be created in RAW")
        with self._lock:
            self._con.execute(f'CREATE OR REPLACE VIEW {schema}."{name}" AS {sql}')

    def replace_table(self, schema: str, name: str, sql: str) -> None:
        if schema.lower() in IMMUTABLE_SCHEMAS:
            raise AppendOnlyViolation("tables in RAW cannot be replaced")
        with self._lock:
            self._con.execute(f'CREATE OR REPLACE TABLE {schema}."{name}" AS {sql}')

    def replace_table_rows(self, schema: str, name: str, cols: Mapping[str, str], rows: list[dict]) -> None:
        if schema.lower() in IMMUTABLE_SCHEMAS:
            raise AppendOnlyViolation("tables in RAW cannot be replaced")
        with self._lock:
            body = ", ".join(f'"{c}" {t}' for c, t in cols.items())
            self._con.execute(f'CREATE OR REPLACE TABLE {schema}."{name}" ({body})')
        self._insert_rows(schema, name, cols, rows)

    @contextmanager
    def deterministic(self):
        """Single-threaded execution so floating-point aggregates are bit-for-bit reproducible (principle 5)."""
        with self._lock:
            prev = self._con.execute("SELECT current_setting('threads')").fetchone()[0]
            self._con.execute("SET threads TO 1")
            try:
                yield self
            finally:
                self._con.execute(f"SET threads TO {int(prev)}")

    @property
    def raw_connection(self) -> duckdb.DuckDBPyConnection:
        """Unguarded connection — read-only analytics only. Never mutate through it."""
        return self._con

    def close(self) -> None:
        self._con.close()


def _arrow_batch(rows: list[Mapping[str, Any]], names: list[str]):
    import pyarrow as pa

    arrays = {}
    for c in names:
        values = [r.get(c) for r in rows]
        try:
            arrays[c] = pa.array(values)
        except (pa.ArrowInvalid, pa.ArrowTypeError, pa.ArrowNotImplementedError):
            safe = [_arrow_safe(v) for v in values]
            try:
                arrays[c] = pa.array(safe)
            except (pa.ArrowInvalid, pa.ArrowTypeError):
                arrays[c] = pa.array([None if v is None else str(v) for v in safe])
    return pa.table(arrays)


def _arrow_safe(v: Any) -> Any:
    if isinstance(v, Decimal):
        return float(v)
    if isinstance(v, (dict, list)):
        return json.dumps(v, sort_keys=True, default=str)
    return v


def _params(params: Any) -> Any:
    """Positional (sequence) or named (mapping, for ``$name`` placeholders) query parameters."""
    if not params:
        return []
    return dict(params) if isinstance(params, Mapping) else list(params)
